module boar_collision (\n    input clk,\n    input rst_n,\n    input start,\n    input [2:0] n,\n    input [15:0] tree0_x, tree0_y, tree0_r,\n    input [15:0] tree1_x, tree1_y, tree1_r,\n    input [15:0] tree2_x, tree1_y, tree2_r,\n    input [15:0] tree3_x, tree3_y, tree3_r,\n    input [15:0] tree4_x, tree4_y, tree4_r,\n    input [15:0] tree5_x, tree5_y, tree5_r,\n    input [15:0] tree6_x, tree6_y, tree6_r,\n    input [15:0] tree7_x, tree7_y, tree7_r,\n    input [15:0] b,\n    input [15:0] d,\n    output reg [31:0] probability,\n    output reg done\n);\n\n    // State declarations\n    localparam [3:0] IDLE          = 4'd0;\n    localparam [3:0] INIT          = 4'd1;\n    localparam [3:0] COMP_ENDPOINT = 4'd2;\n    localparam [3:0] INIT_TREE     = 4'd3;\n    localparam [3:0] CHECK_TREE    = 4'd4;\n    localparam [3:0] NEXT_TREE     = 4'd5;\n    localparam [3:0] COUNT_SAFE    = 4'd6;\n    localparam [3:0] COMP_PROB     = 4'd7;\n    localparam [3:0] DONE_STATE    = 4'd8;\n\n    reg [3:0] state, next_state;\n    reg [3:0] dir_index;\n    reg [2:0] tree_idx;\n    reg [4:0] safe_cnt;\n    reg collision_found;\n    reg [7:0] cycle_cnt;\n    reg [15:0] b_reg;\n    reg [15:0] d_reg;\n    reg [15:0] tree_x_reg, tree_y_reg, tree_r_reg;\n    reg [31:0] x_end, y_end;\n    reg [63:0] len_sq_reg;\n\n    // Precomputed direction vectors in Q16.16 format\n    wire signed [31:0] dir_cos [0:15];\n    wire signed [31:0] dir_sin [0:15];\n\n    assign dir_cos[0]  = 32'sh00010000; assign dir_sin[0]  = 32'sh00000000;\n    assign dir_cos[1]  = 32'sh0000EC83; assign dir_sin[1]  = 32'sh000061F7;\n    assign dir_cos[2]  = 32'sh0000B504; assign dir_sin[2]  = 32'sh0000B504;\n    assign dir_cos[3]  = 32'sh000061F7; assign dir_sin[3]  = 32'sh0000EC83;\n    assign dir_cos[4]  = 32'sh00000000; assign dir_sin[4]  = 32'sh00010000;\n    assign dir_cos[5]  = 32'shFFFF9E09; assign dir_sin[5]  = 32'sh0000EC83;\n    assign dir_cos[6]  = 32'shFFFF4AFC; assign dir_sin[6]  = 32'sh0000B504;\n    assign dir_cos[7]  = 32'shFFFF137D; assign dir_sin[7]  = 32'sh000061F7;\n    assign dir_cos[8]  = 32'shFFFF0000; assign dir_sin[8]  = 32'sh00000000;\n    assign dir_cos[9]  = 32'shFFFF137D; assign dir_sin[9]  = 32'shFFFF9E09;\n    assign dir_cos[10] = 32'shFFFF4AFC; assign dir_sin[10] = 32'shFFFF4AFC;\n    assign dir_cos[11] = 32'shFFFF9E09; assign dir_sin[11] = 32'shFFFF137D;\n    assign dir_cos[12] = 32'sh00000000; assign dir_sin[12] = 32'shFFFF0000;\n    assign dir_cos[13] = 32'sh000061F7; assign dir_sin[13] = 32'shFFFF137D;\n    assign dir_cos[14] = 32'sh0000B504; assign dir_sin[14] = 32'shFFFF4AFC;\n    assign dir_cos[15] = 32'sh0000EC83; assign dir_sin[15] = 32'shFFFF9E09;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            probability <= 32'd0;\n            safe_cnt <= 5'd0;\n            dir_index <= 4'd0;\n            tree_idx <= 3'd0;\n            collision_found <= 1'b0;\n            cycle_cnt <= 8'd0;\n            b_reg <= 16'd0;\n            d_reg <= 16'd0;\n            len_sq_reg <= 64'd0;\n            x_end <= 32'd0;\n            y_end <= 32'd0;\n            tree_x_reg <= 16'd0;\n            tree_y_reg <= 16'd0;\n            tree_r_reg <= 16'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= INIT;\n                        b_reg <= b;\n                        d_reg <= d;\n                    end\n                end\n\n                INIT: begin\n                    dir_index <= 4'd0;\n                    safe_cnt <= 5'd0;\n                    collision_found <= 1'b0;\n                    tree_idx <= 3'd0;\n                    cycle_cnt <= cycle_cnt + 8'd1;\n                    state <= COMP_ENDPOINT;\n                end\n\n                COMP_ENDPOINT: begin\n                    // Compute endpoint for current direction\n                    x_end <= (dir_cos[dir_index] * $signed({1'b0, d_reg})) >>> 16;\n                    y_end <= (dir_sin[dir_index] * $signed({1'b0, d_reg})) >>> 16;\n                    len_sq_reg <= ($signed(x_end)*$signed(x_end)) + ($signed(y_end)*$signed(y_end));\n                    tree_idx <= 3'd0;\n                    collision_found <= 1'b0;\n                    cycle_cnt <= cycle_cnt + 8'd1;\n                    state <= INIT_TREE;\n                end\n\n                INIT_TREE: begin\n                    // Select current tree parameters based on tree_idx\n                    case (tree_idx)\n                        3'd0: begin tree_x_reg <= tree0_x; tree_y_reg <= tree0_y; tree_r_reg <= tree0_r; end\n                        3'd1: begin tree_x_reg <= tree1_x; tree_y_reg <= tree1_y; tree_r_reg <= tree1_r; end\n                        3'd2: begin tree_x_reg <= tree2_x; tree_y_reg <= tree2_y; tree_r_reg <= tree2_r; end\n                        3'd3: begin tree_x_reg <= tree3_x; tree_y_reg <= tree3_y; tree_r_reg <= tree3_r; end\n                        3'd4: begin tree_x_reg <= tree4_x; tree_y_reg <= tree4_y; tree_r_reg <= tree4_r; end\n                        3'd5: begin tree_x_reg <= tree5_x; tree_y_reg <= tree5_y; tree_r_reg <= tree5_r; end\n                        3'd6: begin tree_x_reg <= tree6_x; tree_y_reg <= tree6_y; tree_r_reg <= tree6_r; end\n                        3'd7: begin tree_x_reg <= tree7_x; tree_y_reg <= tree7_y; tree_r_reg <= tree7_r; end\n                    endcase\n                    cycle_cnt <= cycle_cnt + 8'd1;\n                    state <= CHECK_TREE;\n                end\n\n                CHECK_TREE: begin\n                    begin\n                        // Scale tree coordinates to Q16.16\n                        wire signed [31:0] tx_s = $signed({{16{tree_x_reg[15]}}, tree_x_reg}) << 16;\n                        wire signed [31:0] ty_s = $signed({{16{tree_y_reg[15]}}, tree_y_reg}) << 16;\n                        wire signed [31:0] tr_s = {16'd0, tree_r_reg} << 16;\n                        wire signed [31:0] b_s = {16'd0, b_reg} << 16;\n                        wire signed [63:0] threshold_sq = (tr_s + b_s) * (tr_s + b_s);\n\n                        wire signed [63:0] tx_sq = tx_s * tx_s;\n                        wire signed [63:0] ty_sq = ty_s * ty_s;\n                        wire signed [63:0] tx_ty_sq = tx_sq + ty_sq;\n\n                        wire signed [63:0] dot = (tx_s * $signed(x_end)) + (ty_s * $signed(y_end));\n\n                        if ($signed(dot) <= 64'd0) begin\n                            if (tx_ty_sq <= threshold_sq) collision_found <= 1'b1;\n                        end else if ($signed(dot) >= len_sq_reg) begin\n                            wire signed [63:0] dx = tx_s - $signed(x_end);\n                            wire signed [63:0] dy = ty_s - $signed(y_end);\n                            wire signed [63:0] dist_sq = (dx * dx) + (dy * dy);\n                            if (dist_sq <= threshold_sq) collision_found <= 1'b1;\n                        end else begin\n                            wire signed [127:0] lhs = tx_ty_sq * len_sq_reg;\n                            wire signed [127:0] rhs = threshold_sq * len_sq_reg;\n                            wire signed [127:0] dsq_scaled = lhs - (dot * dot);\n                            if (dsq_scaled < rhs) collision_found <= 1'b1;\n                        end\n                    end\n                    cycle_cnt <= cycle_cnt + 8'd1;\n                    state <= NEXT_TREE;\n                end\n\n                NEXT_TREE: begin\n                    if (tree_idx < (n - 3'd1) && !collision_found) begin\n                        tree_idx <= tree_idx + 3'd1;\n                        cycle_cnt <= cycle_cnt + 8'd1;\n                        state <= INIT_TREE;\n                    end else begin\n                        state <= COUNT_SAFE;\n                    end\n                end\n\n                COUNT_SAFE: begin\n                    if (!collision_found) safe_cnt <= safe_cnt + 5'd1;\n\n                    if (dir_index < 4'd15) begin\n                        dir_index <= dir_index + 4'd1;\n                        cycle_cnt <= cycle_cnt + 8'd1;\n                        state <= COMP_ENDPOINT;\n                    end else begin\n                        state <= COMP_PROB;\n                    end\n                end\n\n                COMP_PROB: begin\n                    probability <= {safe_cnt, 12'd0};  // safe_cnt / 16 in Q16.16 format\n                    state <= DONE_STATE;\n                    done <= 1'b1;\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b0;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n\n            // Cycle timeout protection\n            if (cycle_cnt >= 8'd200) begin\n                state <= COMP_PROB;\n                done <= 1'b1;\n            end\n        end\n    end\n\nendmodule\n